// Map a raw Home Assistant weather state to its hero glyph;
// unknown / empty falls back to the cloudy glyph.
inline const freeink::Icon& weatherConditionIcon(const char* condition) {
  struct Row { const char* key; const freeink::Icon* icon; };
  static const Row kRows[] = {
      {"clear-night", &kWx_clear_night},
      {"cloudy", &kWx_cloudy},
      {"exceptional", &kWx_exceptional},
      {"fog", &kWx_fog},
      {"hail", &kWx_hail},
      {"lightning", &kWx_lightning},
      {"lightning-rainy", &kWx_lightning_rainy},
      {"partlycloudy", &kWx_partlycloudy},
      {"pouring", &kWx_pouring},
      {"rainy", &kWx_rainy},
      {"snowy", &kWx_snowy},
      {"snowy-rainy", &kWx_snowy_rainy},
      {"sunny", &kWx_sunny},
      {"windy", &kWx_windy},
      {"windy-variant", &kWx_windy_variant},
      {"night-partlycloudy", &kWx_night_partlycloudy},
  };
  if (condition && *condition) {
    for (const Row& r : kRows) {
      if (strcmp(r.key, condition) == 0) return *r.icon;
    }
  }
  return kWx_cloudy;
}

